notes:
/* ONE THING MOVES. The outline is always whole; focus only
   darkens it in place and parts the top line under the label,
   from its middle outward. */
.lbi-ring path { stroke: rgba(ink, .18); stroke-width: 1; }
.lbi[data-focus] .lbi-ring path { stroke: var(--ink); stroke-width: 1.5; }

/* the gap: two halves from the middle to each side, retracted
   by a negative dash offset */
.lbi-gap { stroke-dasharray: 1 2; transition: stroke-dashoffset 320ms; }
.lbi[data-up] .lbi-gap { stroke-dashoffset: -1; }

/* the label lifts into the top edge, a hop running along it */
.lbi[data-up] .lbi-label { transform: translateY(-50%) translateY(-26px) scale(.78); }
@keyframes hop { 38% { transform: translateY(-3px); } }
